export interface Artifact {
  id: string;
  name: string;
  content: string;
  type: ArtifactType;
  tags: string[];
  metadata: Record<string, unknown>;
  version: number;
  createdAt: Date;
  updatedAt: Date;
}

export type ArtifactType = 
  | 'code'
  | 'document'
  | 'config'
  | 'data'
  | 'image'
  | 'other';

export interface CreateArtifactRequest {
  name: string;
  content: string;
  type: ArtifactType;
  tags?: string[];
  metadata?: Record<string, unknown>;
}

export interface UpdateArtifactRequest {
  name?: string;
  content?: string;
  type?: ArtifactType;
  tags?: string[];
  metadata?: Record<string, unknown>;
}

export interface SearchQuery {
  text?: string;
  tags?: string[];
  type?: ArtifactType;
  startDate?: Date;
  endDate?: Date;
}

export interface ArtifactVersion {
  version: number;
  content: string;
  updatedAt: Date;
  changeDescription?: string;
}

export interface GitHubSyncRequest {
  artifactId: string;
  repository: string;
  branch?: string;
  path: string;
  commitMessage?: string;
}

export interface GitHubSyncStatus {
  artifactId: string;
  repository: string;
  lastSynced: Date | null;
  status: 'synced' | 'pending' | 'error' | 'never';
  commitSha?: string;
  error?: string;
}

export interface PaginatedResponse<T> {
  data: T[];
  total: number;
  page: number;
  pageSize: number;
  hasMore: boolean;
}
