import { v4 as uuidv4 } from 'uuid';
import { 
  Artifact, 
  CreateArtifactRequest, 
  UpdateArtifactRequest, 
  SearchQuery,
  ArtifactVersion,
  PaginatedResponse 
} from '../types';
import { storageService } from './storage-service';

class ArtifactService {
  create(request: CreateArtifactRequest): Artifact {
    const now = new Date();
    const artifact: Artifact = {
      id: uuidv4(),
      name: request.name,
      content: request.content,
      type: request.type,
      tags: request.tags || [],
      metadata: request.metadata || {},
      version: 1,
      createdAt: now,
      updatedAt: now,
    };

    storageService.saveArtifact(artifact);
    storageService.saveVersion(artifact.id, {
      version: 1,
      content: artifact.content,
      updatedAt: now,
    });

    return artifact;
  }

  getById(id: string): Artifact | null {
    return storageService.getArtifact(id);
  }

  getAll(page: number = 1, pageSize: number = 10): PaginatedResponse<Artifact> {
    const allArtifacts = storageService.getAllArtifacts();
    const start = (page - 1) * pageSize;
    const end = start + pageSize;
    const data = allArtifacts.slice(start, end);

    return {
      data,
      total: allArtifacts.length,
      page,
      pageSize,
      hasMore: end < allArtifacts.length,
    };
  }

  update(id: string, request: UpdateArtifactRequest): Artifact | null {
    const existing = storageService.getArtifact(id);
    if (!existing) {
      return null;
    }

    const now = new Date();
    const updated: Artifact = {
      ...existing,
      name: request.name ?? existing.name,
      content: request.content ?? existing.content,
      type: request.type ?? existing.type,
      tags: request.tags ?? existing.tags,
      metadata: request.metadata ?? existing.metadata,
      version: existing.version + 1,
      updatedAt: now,
    };

    storageService.saveArtifact(updated);

    if (request.content && request.content !== existing.content) {
      storageService.saveVersion(id, {
        version: updated.version,
        content: updated.content,
        updatedAt: now,
      });
    }

    return updated;
  }

  delete(id: string): boolean {
    return storageService.deleteArtifact(id);
  }

  getVersions(id: string): ArtifactVersion[] {
    return storageService.getVersions(id);
  }

  search(query: SearchQuery): Artifact[] {
    const allArtifacts = storageService.getAllArtifacts();

    return allArtifacts.filter(artifact => {
      if (query.text) {
        const searchText = query.text.toLowerCase();
        const matchesText = 
          artifact.name.toLowerCase().includes(searchText) ||
          artifact.content.toLowerCase().includes(searchText);
        if (!matchesText) return false;
      }

      if (query.tags && query.tags.length > 0) {
        const hasAllTags = query.tags.every(tag => 
          artifact.tags.includes(tag)
        );
        if (!hasAllTags) return false;
      }

      if (query.type && artifact.type !== query.type) {
        return false;
      }

      if (query.startDate && artifact.createdAt < query.startDate) {
        return false;
      }

      if (query.endDate && artifact.createdAt > query.endDate) {
        return false;
      }

      return true;
    });
  }
}

export const artifactService = new ArtifactService();
